select count(1)
from game_poem_maze_user_line
where user_id = #{userId}
and level_id = #{levelId}
and line_index = #{lineIndex}

select line_index
from game_poem_maze_user_line
where user_id = #{userId}
and level_id = #{levelId}
order by line_index asc

select ifnull(sum(score), 0)
from game_poem_maze_user_line
where user_id = #{userId}
and season_no = #{seasonNo}
